{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A 99mTc-labeled 1-thio-beta-D-glucose showed the lowest brain uptake on scintigraphy, indicating that a polar monosaccharide glycoside without a lipophilic aglycone is incapable of crossing the BBB; the query disaccharide is even more polar and larger.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Me-4FDG, a glucose derivative, did not enter the human brain by PET, demonstrating that glucose-like glycosides are not inherently BBB-permeable and require specific transporter recognition; sucrose is not a known GLUT/SGLT substrate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Gastrodin, a phenolic glucoside more lipophilic than sucrose, had only a 5.5% CSF/plasma ratio in rats, indicating poor brain penetration for glycosides; sucrose, lacking any aglycone, would be expected to penetrate even less.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Gastrodin was detected in mouse brain after intravenous injection and is considered BBB-permeable, but this is attributed to its lipophilic phenolic aglycone and/or transporter-mediated handling; the query sucrose has no such aglycone and is not a transporter substrate.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Sucrose is a highly polar, non-reducing disaccharide with no lipophilic aglycone and no known glucose-transporter recognition. Direct evidence from polar glycoside and glucose analogues shows poor or absent brain uptake, so meaningful CNS access is not expected.",
  "evidence_gaps": [
    "No direct sucrose brain-uptake record is present in the evidence set.",
    "Most permeable glycoside analogues contain lipophilic aglycones or are transporter substrates, so extrapolation relies on structural analogy and the known BBB-impermeant behavior of sucrose."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

